import{_ as e,o,c as d,a2 as a}from"./chunks/framework.vLhlLNVn.js";const r="/assets/detailansicht.iO2JD4_C.png",q=JSON.parse('{"title":"Settings (instance and datapoint)","description":"","frontmatter":{"order":1,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/03.referenz/01.einstellungen.md"},"headers":[],"relativePath":"adapter/sourceanalytix/referenz/einstellungen.md","filePath":"adapter/sourceanalytix/referenz/einstellungen.md","lastUpdated":null}'),s={name:"adapter/sourceanalytix/referenz/einstellungen.md"};function n(i,t,u,c,h,l){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="settings-instance-and-datapoint" tabindex="-1">Settings (instance and datapoint) <a class="header-anchor" href="#settings-instance-and-datapoint" aria-label="Permalink to &quot;Settings (instance and datapoint)&quot;">​</a></h1><p><a id="units-supported-energy-volume-weight"></a></p><h2 id="which-units-are-supported-energy-volume-weight-length" tabindex="-1">Which units are supported (energy, volume, weight, length)? <a class="header-anchor" href="#which-units-are-supported-energy-volume-weight-length" aria-label="Permalink to &quot;Which units are supported (energy, volume, weight, length)?&quot;">​</a></h2><p>Power, energy, volume, mass, length and pieces. Conversion works within the same quantity and between litres and cubic metres. Power and pulses per minute are summed up over time.</p><table tabindex="0"><thead><tr><th>Quantity</th><th>Units</th><th>Converts to</th></tr></thead><tbody><tr><td>Power</td><td><code>GW</code>, <code>MW</code>, <code>kW</code>, <code>W</code>, <code>mW</code></td><td>energy, summed up over time</td></tr><tr><td>Energy</td><td><code>GWh</code>, <code>MWh</code>, <code>kWh</code>, <code>Wh</code>, <code>mWh</code></td><td>any energy unit</td></tr><tr><td>Volume</td><td><code>km³</code>, <code>m³</code>, <code>dm³</code>, <code>cm³</code>, <code>mm³</code>, <code>hl</code>, <code>l</code>, <code>dl</code>, <code>cl</code>, <code>ml</code></td><td>any volume unit (1 <code>m³</code> = 1,000 <code>l</code>)</td></tr><tr><td>Mass</td><td><code>t</code>, <code>kg</code>, <code>g</code></td><td>any mass unit</td></tr><tr><td>Length</td><td><code>km</code>, <code>m</code>, <code>dm</code>, <code>cm</code>, <code>mm</code>, <code>µm</code>, <code>nm</code></td><td>any length unit</td></tr><tr><td>Pieces</td><td><code>piece</code></td><td>any unit, with &quot;Pulses per unit&quot;</td></tr><tr><td>Pulses per minute</td><td><code>piece/min</code></td><td>like <code>piece</code>, summed up over time</td></tr></tbody></table><p>On the object, SourceAnalytix also recognises spellings such as <code>m3</code>, <code>kwh</code>, <code>L</code>, <code>Stk</code> or <code>pulses/min</code>. Not supported are time (<code>h</code>), data volumes, rates such as <code>m³/h</code>, and quantities such as <code>%</code> or <code>V</code>.</p><h3 id="which-unit-applies-where" tabindex="-1">Which unit applies where? <a class="header-anchor" href="#which-unit-applies-where" aria-label="Permalink to &quot;Which unit applies where?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Meaning</th></tr></thead><tbody><tr><td>&quot;Unit&quot; on the source</td><td>the unit the datapoint <strong>delivers</strong>, usually detected automatically</td></tr><tr><td>&quot;Unit&quot; in the price definition</td><td>the unit SourceAnalytix <strong>calculates and displays</strong> in; start values and price refer to it</td></tr></tbody></table><p>If the two don&#39;t fit together, say <code>kg</code> and <code>kWh</code>, the source does not start and the &quot;Problems&quot; tab reports it.</p><h3 id="pieces-and-pulses" tabindex="-1">Pieces and pulses <a class="header-anchor" href="#pieces-and-pulses" aria-label="Permalink to &quot;Pieces and pulses&quot;">​</a></h3><ul><li><strong>Just counting</strong>, for example burner starts: price definition in <code>piece</code>.</li><li><strong>Pulses into kWh or m³:</strong> enter &quot;Pulses per unit&quot;, for example <code>1000</code> for 1000 imp/kWh. In the wizard the field is in the &quot;Price&quot; step, in the detail view under &quot;Settings&quot;.</li><li><strong>Every update is a pulse:</strong> set &quot;Each update adds its value&quot; under &quot;For experts&quot;. Then every update counts, even with the same value.</li></ul><p><strong>See also:</strong> <a href="./../anleitungen/quellen-und-einheiten#unit-datapoint-kwh-wh-m3">Which unit do I set on the datapoint?</a> · <a href="./../fehlerbehebung/log-meldungen#error-unit-not-supported-no">&quot;No unit defined&quot; error</a></p><p><a id="instance-settings-exist-periods-decimals"></a></p><h2 id="which-instance-settings-are-there-periods-decimals" tabindex="-1">Which instance settings are there (periods, decimals)? <a class="header-anchor" href="#which-instance-settings-are-there-periods-decimals" aria-label="Permalink to &quot;Which instance settings are there (periods, decimals)?&quot;">​</a></h2><p>Four tabs. &quot;Main settings&quot; decides which week, month and quarter states are created and how many decimals new sources get.</p><table tabindex="0"><thead><tr><th>Tab</th><th>Content</th><th>Takes effect</th></tr></thead><tbody><tr><td>&quot;Overview&quot;</td><td>all sources with values, &quot;Add source&quot;, detail view</td><td>actions with ⚡ immediately</td></tr><tr><td>&quot;Problems&quot;</td><td>findings with a suggested fix</td><td>immediately</td></tr><tr><td>&quot;Price definitions&quot;</td><td>the price table</td><td>after &quot;Save&quot; (restart)</td></tr><tr><td>&quot;Main settings&quot;</td><td>periods and rounding</td><td>after &quot;Save&quot; (restart)</td></tr></tbody></table><h3 id="the-main-settings-tab" tabindex="-1">The &quot;Main settings&quot; tab <a class="header-anchor" href="#the-main-settings-tab" aria-label="Permalink to &quot;The &quot;Main settings&quot; tab&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Section</th><th>Option</th><th>Default</th><th>Creates</th></tr></thead><tbody><tr><td>&quot;Year statistics&quot;</td><td>&quot;Weeks&quot;</td><td>off</td><td><code>&lt;year&gt;.&lt;category&gt;.weeks.01</code> to <code>53</code></td></tr><tr><td>&quot;Year statistics&quot;</td><td>&quot;Months&quot;</td><td>on</td><td><code>&lt;year&gt;.&lt;category&gt;.months.01_January</code> to <code>12_December</code></td></tr><tr><td>&quot;Year statistics&quot;</td><td>&quot;Quarters&quot;</td><td>off</td><td><code>&lt;year&gt;.&lt;category&gt;.quarters.Q1</code> to <code>Q4</code></td></tr><tr><td>&quot;Current year&quot;</td><td>&quot;Weekday&quot;</td><td>on</td><td><code>currentYear.&lt;category&gt;.currentWeek.01_Monday</code> to <code>07_Sunday</code></td></tr><tr><td>&quot;Current year&quot;</td><td>&quot;Weeks&quot;, &quot;Months&quot;, &quot;Quarters&quot;</td><td>on</td><td><code>currentYear.&lt;category&gt;.weeks</code>, <code>months</code>, <code>quarters</code></td></tr><tr><td>&quot;Current year&quot;</td><td>&quot;Previous period&quot;</td><td>on</td><td><code>01_previousDay</code> to <code>05_previousYear</code></td></tr><tr><td>&quot;Rounding&quot;</td><td>decimals for consumption / costs</td><td>3 / 2</td><td>template for new sources</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>If you turn a period option off, SourceAnalytix deletes those states of all sources for the current year when you save. The page asks first. Earlier years and recordings in the history adapter stay.</p></div><p>If a state is missing, the option is usually off, or the source lacks &quot;Consumption&quot;, &quot;Costs&quot; or &quot;Store meter readings&quot;. Previous periods stay at 0 until the first period rollover.</p><p>Each source takes over the decimals once when it is created. After that, change them in the detail view under &quot;For experts&quot;. Allowed are 0 to 15; -1 means unrounded. <code>cumulativeReading</code> always stays unrounded.</p><p><strong>See also:</strong> <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#so-many-decimals">Why so many decimal places?</a> · <a href="./../anleitungen/werte-auswerten#evaluate-across-years-adjusting-everything">Evaluating across several years</a></p><p><a id="datapoint-settings-costs-consumption-meter"></a></p><h2 id="what-do-the-datapoint-settings-do-costs-consumption-meter-values" tabindex="-1">What do the datapoint settings do (Costs, Consumption, Meter values)? <a class="header-anchor" href="#what-do-the-datapoint-settings-do-costs-consumption-meter-values" aria-label="Permalink to &quot;What do the datapoint settings do (Costs, Consumption, Meter values)?&quot;">​</a></h2><p>They decide what SourceAnalytix calculates for the source and which states are created. You find them in the source&#39;s detail view under &quot;Settings&quot;; &quot;⚡ Apply&quot; takes effect immediately.</p><p><img src="'+r+'" alt="A source&#39;s detail view with &quot;Values&quot;, &quot;Settings&quot; and &quot;Actions&quot;"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th><th>Default</th></tr></thead><tbody><tr><td>&quot;Name&quot;</td><td>display name, does not change any state ID</td><td>the datapoint&#39;s name</td></tr><tr><td>&quot;Unit&quot;</td><td>the unit the datapoint delivers</td><td>detected</td></tr><tr><td>&quot;Price definition&quot;</td><td>required; target unit, costs or earnings</td><td>–</td></tr><tr><td>&quot;Consumption&quot;</td><td>states under <code>consumed</code> or <code>delivered</code></td><td>on</td></tr><tr><td>&quot;Costs&quot;</td><td>states under <code>costs</code> or <code>earnings</code></td><td>on</td></tr><tr><td>&quot;Include basic fee&quot;</td><td>books the &quot;Price per month&quot;</td><td>on if no other source books it</td></tr><tr><td>&quot;Store meter readings&quot;</td><td>readings per period under <code>meterReadings</code></td><td>on</td></tr><tr><td>&quot;Reset detection&quot;</td><td>catches drops to 0</td><td>off, on for Shelly and Tasmota</td></tr><tr><td>&quot;Ignore negative values&quot;</td><td>power only: negative values count as 0</td><td>off</td></tr><tr><td>&quot;Average power values&quot;</td><td>power only: average of two values</td><td>off</td></tr><tr><td>&quot;Maximum gap between power values (minutes)&quot;</td><td>power only: longer pauses count as 0</td><td>empty = off</td></tr><tr><td>&quot;Pulses per unit&quot;</td><td>pieces only: conversion into the target unit</td><td>empty</td></tr><tr><td>&quot;Start values&quot;</td><td>reading at the start of the periods</td><td>empty = from now</td></tr><tr><td>For experts: &quot;Reset detection threshold&quot;</td><td>largest drop that counts as jitter</td><td>1</td></tr><tr><td>For experts: &quot;Decimals for consumption&quot; / &quot;Decimals for costs&quot;</td><td>rounding of the states</td><td>3 / 2</td></tr><tr><td>For experts: &quot;Each update adds its value&quot;</td><td>every update counts as an increase</td><td>off</td></tr><tr><td>For experts: &quot;Technical ID&quot;</td><td>folder <code>sourceanalytix.0.&lt;device&gt;</code></td><td>from the name</td></tr></tbody></table><p>Numbers work with a comma or a dot, without a thousands separator. The page marks invalid fields and does not save. If a change deletes data, for example switching off &quot;Consumption&quot; or &quot;Costs&quot; or switching between &quot;Costs&quot; and &quot;Earnings&quot;, the page asks first with &quot;Delete data?&quot;.</p><p>On the datapoint on the &quot;Objects&quot; tab, there is only an on/off switch. Switching it off there removes the source&#39;s settings; to pause, use &quot;Deactivate&quot;.</p><h3 id="when-meterreadings-stays-empty" tabindex="-1">When <code>meterReadings</code> stays empty <a class="header-anchor" href="#when-meterreadings-stays-empty" aria-label="Permalink to &quot;When `meterReadings` stays empty&quot;">​</a></h3><p><code>meterReadings</code> holds the total at the end of a period. The folder stays empty if &quot;Store meter readings&quot; is off, the instance&#39;s period options are off, or the first period rollover is still pending. The current reading is in <code>cumulativeReading</code>.</p><p><strong>See also:</strong> <a href="./states-und-meldungen#meter-readings-cumulative">Meter readings and cumulativeReading</a> · <a href="./../fehlerbehebung/log-meldungen#datapoint-enabled-but-no-folders">Datapoint enabled, but no folders</a></p><p><a id="threshold-disabling-reset-detection-work"></a></p><h2 id="how-do-the-threshold-and-turning-off-reset-detection-work" tabindex="-1">How do the threshold and turning off reset detection work? <a class="header-anchor" href="#how-do-the-threshold-and-turning-off-reset-detection-work" aria-label="Permalink to &quot;How do the threshold and turning off reset detection work?&quot;">​</a></h2><p>You set both per source: &quot;Reset detection&quot; under &quot;Settings&quot;, the threshold under &quot;For experts&quot;. The threshold (default 1, in the unit of the price definition) is the largest drop that still counts as measurement jitter.</p><table tabindex="0"><thead><tr><th>Drop</th><th>Reset detection on</th><th>off</th></tr></thead><tbody><tr><td>up to the threshold</td><td>is ignored</td><td>the total drops with it</td></tr><tr><td>larger</td><td>SourceAnalytix waits for the next value and then keeps counting</td><td>the total drops, periods can turn negative</td></tr></tbody></table><p>The threshold must be larger than the device&#39;s noise and smaller than the reading it restarts with after a reset. 0 means every drop is a possible reset. Empty counts as the default of 1.</p><p>Power, <code>piece/min</code> and &quot;Each update adds its value&quot; have no reset detection. If a source without reset detection drops to 0, the &quot;Problems&quot; tab reports &quot;Meter drops to 0, reset detection is off&quot; with &quot;Switch on&quot;.</p><p><strong>See also:</strong> <a href="./../anleitungen/zaehlerstaende-korrigieren#meter-restarts-after-power-loss">Meter restarts at 0 after a power failure</a> · <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">What does &quot;Device reset detected&quot; mean?</a></p><p><a id="price-definition-structured-categories-base"></a></p><h2 id="how-is-a-price-definition-structured-categories-basic-fee-decimal-mark" tabindex="-1">How is a price definition structured (categories, basic fee, decimal mark)? <a class="header-anchor" href="#how-is-a-price-definition-structured-categories-basic-fee-decimal-mark" aria-label="Permalink to &quot;How is a price definition structured (categories, basic fee, decimal mark)?&quot;">​</a></h2><p>As a row on the &quot;Price definitions&quot; tab with a name (&quot;Category&quot;), unit, cost type and price. Each source has exactly one. The basic fee is booked in full once a month, not pro rata per day.</p><table tabindex="0"><thead><tr><th>Column</th><th>Meaning</th></tr></thead><tbody><tr><td>&quot;Category&quot;</td><td>unique name, for example <code>Power</code>; not empty and not duplicated</td></tr><tr><td>&quot;Description&quot;</td><td>free text</td></tr><tr><td>&quot;Cost Type&quot;</td><td>&quot;Costs&quot; (<code>consumed</code>, <code>costs</code>) or &quot;Earnings&quot; (<code>delivered</code>, <code>earnings</code>)</td></tr><tr><td>&quot;Unit&quot;</td><td>the unit used for calculation and display</td></tr><tr><td>&quot;Price source&quot;</td><td>&quot;Fixed price&quot;, &quot;Datapoint&quot; or &quot;Tariff selector&quot;</td></tr><tr><td>&quot;Price per unit&quot;</td><td>for example <code>0.32</code> for €0.32/kWh</td></tr><tr><td>&quot;Price state&quot;</td><td>state with the price or tariff</td></tr><tr><td>&quot;Active tariff price&quot;, &quot;Active selector value&quot;</td><td>only with &quot;Tariff selector&quot;</td></tr><tr><td>&quot;Valid from&quot;</td><td>the prices apply from 0:00 on this day</td></tr><tr><td>&quot;Price per month&quot;</td><td>basic fee</td></tr></tbody></table><p>Comma and dot both work, without a thousands separator. If a price is not a number, SourceAnalytix calculates with 0 and logs it. <code>sourceanalytix.0.priceDefinitions.&lt;category&gt;.currentPrice</code> shows whether it arrived correctly. Changes apply after &quot;Save&quot;.</p><p>Details on price sources, &quot;Valid from&quot; and the basic fee are under <a href="./../anleitungen/preise-und-kosten#costs-recalculated-change-price-change">Prices and costs</a>.</p><p><strong>See also:</strong> <a href="./states-und-meldungen#prices-read-written-as-states">Prices as states</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#costs-stay-0-not-calculated">Costs stay 0</a></p><p><a id="name-datapoint-alias-output-id"></a></p><h2 id="how-do-i-name-the-datapoint-alias-output-id" tabindex="-1">How do I name the datapoint (alias, output ID)? <a class="header-anchor" href="#how-do-i-name-the-datapoint-alias-output-id" aria-label="Permalink to &quot;How do I name the datapoint (alias, output ID)?&quot;">​</a></h2><p>A source has two names. The &quot;Name&quot; is for display only and can be changed at any time. The &quot;Technical ID&quot; is the folder <code>sourceanalytix.0.&lt;device&gt;</code> with all states; it is best set when you create the source.</p><p>The wizard derives the technical ID from the name, for example <code>house_power</code> from &quot;House power&quot;, and otherwise falls back to the datapoint ID. Letters, digits, <code>_</code> and <code>-</code> are allowed. The ID must be unique; <code>info</code>, <code>priceDefinitions</code>, <code>priceHistory</code> and <code>basicPriceHistory</code> are reserved.</p><p>If you change the ID in the detail view under &quot;For experts&quot;, SourceAnalytix copies the whole folder to the new ID and then deletes the old one. You have to adapt scripts, VIS views and history queries yourself; old recordings stay under the old ID.</p><p><strong>See also:</strong> <a href="./../erste-schritte/erster-zaehler#values-consumption-today-yesterday">Where do I find my values?</a> · <a href="./../anleitungen/werte-auswerten#read-sourceanalytix-values-script">Reading values in a script</a></p><p><a id="source-types-exist-meter-power"></a></p><h2 id="which-source-types-are-there-meter-power" tabindex="-1">Which source types are there (meter, power)? <a class="header-anchor" href="#which-source-types-are-there-meter-power" aria-label="Permalink to &quot;Which source types are there (meter, power)?&quot;">​</a></h2><p>Two. A <strong>meter reading</strong> keeps rising, and consumption is the difference. A <strong>power</strong> value is an instantaneous value that SourceAnalytix sums up over time. The type follows from the unit.</p><table tabindex="0"><thead><tr><th></th><th>Meter reading</th><th>Power</th></tr></thead><tbody><tr><td>Units</td><td>energy, volume, mass, length, <code>piece</code></td><td>power, <code>piece/min</code></td></tr><tr><td><code>cumulativeReading</code></td><td>device value + offset</td><td>starts at 0</td></tr><tr><td>Reset detection, start values</td><td>yes</td><td>no</td></tr><tr><td>&quot;Meter swapped&quot;</td><td>yes</td><td>no</td></tr></tbody></table><p>&quot;Each update adds its value&quot; behaves like power. Whether import or feed-in is counted depends on the price definition&#39;s &quot;Cost Type&quot;.</p><p><strong>See also:</strong> <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Meter or power?</a> · <a href="./../hintergrund/berechnung#sourceanalytix-convert-watts-kwh">Watts to kWh</a></p>',58)])])}const m=e(s,[["render",n]]);export{q as __pageData,m as default};
